using System;
using System.Collections.Generic;
using UnityEngine;

// Remodeled unit art with a 4-frame idle loop, generated by Tools/PixelArt (`node heroes.js --export`, `node enemies.js --export`).
//   Heroes:  Resources/Heroes/<id>_<frame>.png, 22x27 (exact 4x in the 88x108 combat box), keyed by the Art row arrays
//            so every existing `sprite = Art.X` reference picks them up.
//   Enemies: Resources/Enemies/<id>_<frame>.png, 24x26 (4x in 96x104) or 48x60 for bosses (4x in 192x240), keyed by enemy id,
//            since several roster enemies share one Art row array. Legacy enemies fall back to the closest new art by rows.
// Units with no remodeled art keep drawing from their rows.
namespace Obscure
{
    public static class UnitArt
    {
        public static readonly float[] IdleDelays = { 0.32f, 0.18f, 0.32f, 0.18f };
        const float IdleLength = 1f; // sum of IdleDelays

        static readonly Dictionary<string[], string> heroes = new Dictionary<string[], string>
        {
            [Art.Knight] = "knight",
            [Art.Fighter] = "fighter",
            [Art.Barbarian] = "barbarian",
            [Art.MartialArtist] = "martial_artist",
            [Art.Rogue] = "rogue",
            [Art.Ranger] = "ranger",
            [Art.Healer] = "cleric", // shared by the Cleric class and the legacy Healer
            [Art.Mage] = "wizard",   // shared by the Wizard class and the legacy Mage
            [Art.Warlock] = "warlock",
            [Art.Druid] = "druid",
        };

        static readonly HashSet<string> enemies = new HashSet<string>
        {
            "hollow_squire", "gravebound_archer", "cinder_wisp", "soulbound_hound", "possessed_royal_guard",
            "crypt_leech", "forgotten_militia", "soul_reaper", "royal_ossuary_knight", "zoroa_p1", "zoroa_p2",
            "reliquary_confessor", "graveglass_arcanist", "crownless_duelist", "tombstone_colossus", "mourning_bell_wraith", // roster v1.9 Elites
            "ossuary_acolyte", "dirge_chanter", "hollow_banneret", // common supports
            // Tutorial Prologue (Tools/PixelArt/prologue.js); aetherion_p2 is art only, shown once Aetherion reaches phase 2
            "riftling", "shard_wisp", "veil_stalker", "aetherion", "aetherion_p2",
        };

        static string BaseArtId(string enemyId) =>
            enemyId != null && enemyId.EndsWith("_enhanced", StringComparison.Ordinal)
                ? enemyId.Substring(0, enemyId.Length - "_enhanced".Length)
                : enemyId;

        // Art id for an enemy in its current boss phase. Zoroa swaps to a separate zoroa_p2 def; a boss that changes phase
        // in place (phase2At, e.g. Aetherion) shows "<id>_p2" art from phase 2 on when that art exists.
        public static string EnemyArtId(string enemyId, int phase)
        {
            string baseId = BaseArtId(enemyId);
            return baseId != null && phase > 1 && enemies.Contains(baseId + "_p2") ? baseId + "_p2" : baseId;
        }

        // Legacy enemies (Skeleton Warrior, Cursed Knight, Abyssal Warden) reuse the closest Dungeon 1 art.
        static readonly Dictionary<string[], string> legacyEnemies = new Dictionary<string[], string>
        {
            [Art.Skeleton] = "hollow_squire",
            [Art.CursedKnight] = "royal_ossuary_knight",
            [Art.Warden] = "zoroa_p1",
        };

        static readonly Dictionary<string, Texture2D[]> cache = new Dictionary<string, Texture2D[]>();

        // Hero idle frames for a sprite's rows, or null when there is no remodeled art for it.
        public static Texture2D[] Idle(string[] rows) =>
            rows != null && heroes.TryGetValue(rows, out var id) ? Load("Heroes/" + id) : null;

        // Enemy idle frames by enemy id (falling back to legacy rows), or null to keep the row art.
        public static Texture2D[] Enemy(string enemyId, string[] rows)
        {
            string baseId = BaseArtId(enemyId);
            if (baseId != null && enemies.Contains(baseId)) return Load("Enemies/" + baseId);
            return rows != null && legacyEnemies.TryGetValue(rows, out var id) ? Load("Enemies/" + id) : null;
        }

        // A one-shot hero combat clip: "act" (attack / shot / cast, by class), "hit" or "ko".
        // Frames are Resources/Heroes/<id>_<clip>_<i>.png; delays and the strike frame come from Resources/Heroes/clips.json,
        // both written by `node anims.js --export`.
        public class Clip
        {
            public Texture2D[] frames;
            public float[] delays;
            public string style;  // melee | shoot | cast | hit | ko; enemies also pounce | reap
            public int strike;    // frame the blow lands on, -1 when the clip has none
            public float TimeTo(int frame) { float t = 0; for (int i = 0; i < frame && i < delays.Length; i++) t += delays[i]; return t; }
        }

        [Serializable] class ClipJson { public string hero, clip, style; public int strike; public float[] delays; }
        [Serializable] class ClipList { public ClipJson[] clips; }
        static readonly Dictionary<string, Dictionary<string, ClipJson>> clipInfo = new Dictionary<string, Dictionary<string, ClipJson>>();
        static readonly Dictionary<string, Clip> clipCache = new Dictionary<string, Clip>();

        public static Clip HeroClip(string[] rows, string clip) =>
            rows != null && heroes.TryGetValue(rows, out var id) ? LoadClip("Heroes", id, clip) : null;

        // An enemy's attack clip ("atk"), found the same way as its idle art: by enemy id, then legacy rows.
        // Frames are Resources/Enemies/<id>_atk_<i>.png, timings Resources/Enemies/clips.json (`node anims.js --export-enemies`).
        public static Clip EnemyClip(string enemyId, string[] rows)
        {
            string baseId = BaseArtId(enemyId);
            if (baseId != null && enemies.Contains(baseId)) return LoadClip("Enemies", baseId, "atk");
            return rows != null && legacyEnemies.TryGetValue(rows, out var id) ? LoadClip("Enemies", id, "atk") : null;
        }

        static Clip LoadClip(string folder, string id, string clip)
        {
            string key = folder + "/" + id + "_" + clip;
            if (clipCache.TryGetValue(key, out var c) && (c == null || c.frames[0] != null)) return c;
            if (!clipInfo.TryGetValue(folder, out var infos))
            {
                clipInfo[folder] = infos = new Dictionary<string, ClipJson>();
                var json = Resources.Load<TextAsset>(folder + "/clips");
                if (json != null)
                    foreach (var j in JsonUtility.FromJson<ClipList>(json.text).clips) infos[j.hero + "_" + j.clip] = j;
            }
            if (!infos.TryGetValue(id + "_" + clip, out var info)) return clipCache[key] = null;
            var frames = Load(key, info.delays.Length);
            return clipCache[key] = frames == null ? null : new Clip { frames = frames, delays = info.delays, style = info.style, strike = info.strike };
        }

        static Texture2D[] Load(string path, int count = 4)
        {
            if (cache.TryGetValue(path, out var frames) && (frames == null || frames[0] != null)) return frames;
            frames = new Texture2D[count];
            for (int i = 0; i < frames.Length; i++)
            {
                frames[i] = Resources.Load<Texture2D>($"{path}_{i}");
                if (frames[i] == null) return cache[path] = null;
                frames[i].filterMode = FilterMode.Point;
            }
            return cache[path] = frames;
        }

        // Frame index of the idle loop at time t (seconds).
        public static int FrameAt(float t)
        {
            t = Mathf.Repeat(t, IdleLength);
            for (int i = 0; i < IdleDelays.Length; i++)
            {
                if (t < IdleDelays[i]) return i;
                t -= IdleDelays[i];
            }
            return IdleDelays.Length - 1;
        }
    }
}
